#!/usr/bin/env python3
from pathlib import Path
import shutil
import subprocess
import sys

target = Path(sys.argv[1] if len(sys.argv) > 1 else "server.js")
if not target.exists():
    raise SystemExit(f"ERRO: {target} nao encontrado.")

text = target.read_text(encoding="utf-8")

if "class EchoActiveFtpClient" in text:
    print("Patch FTP ativo ja esta presente. Nenhuma alteracao feita.")
    raise SystemExit(0)

old = 'async function connectFtp(mode) {\n  const profile = ftpProfile(mode);\n  const client = new ftp.Client(profile.timeoutMs || 15000);\n  client.ftp.verbose = false;\n\n  await client.access({\n    host: config.xbox.host,\n    port: profile.port,\n    user: profile.username,\n    password: profile.password,\n    secure: false\n  });\n\n  return client;\n}'
new = 'async function connectFtp(mode) {\n  const profile = ftpProfile(mode);\n\n  if (mode === "background") {\n    const client = new EchoActiveFtpClient(profile.timeoutMs || 15000);\n    await client.access({\n      host: config.xbox.host,\n      port: profile.port,\n      user: profile.username,\n      password: profile.password\n    });\n    return client;\n  }\n\n  const client = new ftp.Client(profile.timeoutMs || 15000);\n  client.ftp.verbose = false;\n\n  await client.access({\n    host: config.xbox.host,\n    port: profile.port,\n    user: profile.username,\n    password: profile.password,\n    secure: false\n  });\n\n  return client;\n}'
active = 'function ftpDllPath(remote) {\n  const canonical = normalizeRemote(remote);\n  if (canonical === "/") return "/";\n\n  const parts = canonical.split("/").filter(Boolean);\n  if (!parts.length) return "/";\n\n  const original = parts.shift();\n  const roots = {\n    hdd1: "fHdd",\n    usb0: "fUsb0",\n    flash: "fFlash",\n    fhdd: "fHdd",\n    fusb0: "fUsb0",\n    fflash: "fFlash"\n  };\n  const mapped = roots[String(original).toLowerCase()] || original;\n  return "/" + [mapped, ...parts].join("/");\n}\n\nfunction ftpDllRootDisplayName(name) {\n  const roots = {\n    fhdd: "Hdd1",\n    fusb0: "Usb0",\n    fflash: "Flash"\n  };\n  return roots[String(name).toLowerCase()] || name;\n}\n\nclass EchoActiveFtpClient {\n  constructor(timeoutMs = 15000) {\n    this.timeoutMs = timeoutMs;\n    this.control = null;\n    this.buffer = "";\n    this.lines = [];\n    this.waiters = [];\n    this.deadError = null;\n    this.progress = null;\n    this.host = null;\n    this.port = null;\n  }\n\n  async access(options) {\n    this.host = options.host;\n    this.port = options.port;\n    this.timeoutMs = options.timeoutMs || this.timeoutMs;\n\n    this.control = net.createConnection({\n      host: this.host,\n      port: this.port\n    });\n    this.control.setEncoding("utf8");\n\n    this.control.on("data", chunk => {\n      this.buffer += chunk;\n      while (true) {\n        const idx = this.buffer.indexOf("\\n");\n        if (idx < 0) break;\n        let line = this.buffer.slice(0, idx);\n        this.buffer = this.buffer.slice(idx + 1);\n        if (line.endsWith("\\r")) line = line.slice(0, -1);\n        this._pushLine(line);\n      }\n    });\n\n    const fail = err => this._fail(err instanceof Error ? err : new Error(String(err)));\n    this.control.on("error", fail);\n    this.control.on("close", () => {\n      if (!this.deadError) this._fail(new Error("FTP control socket closed."));\n    });\n\n    await new Promise((resolve, reject) => {\n      const timer = setTimeout(() => {\n        reject(new Error(`Timeout conectando ao FTP ${this.host}:${this.port}`));\n        this.control.destroy();\n      }, this.timeoutMs);\n\n      this.control.once("connect", () => {\n        clearTimeout(timer);\n        resolve();\n      });\n      this.control.once("error", err => {\n        clearTimeout(timer);\n        reject(err);\n      });\n    });\n\n    const hello = await this._readResponse();\n    this._assertOk(hello, "banner");\n\n    let response = await this._send(`USER ${options.user}`);\n    if (response.code === 331) {\n      response = await this._send(`PASS ${options.password}`);\n    }\n    if (response.code !== 230) {\n      throw new Error(`FTP login falhou: ${response.code} ${response.message}`);\n    }\n\n    response = await this._send("TYPE I");\n    this._assertOk(response, "TYPE I");\n  }\n\n  _pushLine(line) {\n    const waiter = this.waiters.shift();\n    if (waiter) waiter.resolve(line);\n    else this.lines.push(line);\n  }\n\n  _fail(error) {\n    this.deadError = error;\n    while (this.waiters.length) {\n      this.waiters.shift().reject(error);\n    }\n  }\n\n  _nextLine() {\n    if (this.lines.length) return Promise.resolve(this.lines.shift());\n    if (this.deadError) return Promise.reject(this.deadError);\n\n    return new Promise((resolve, reject) => {\n      const timer = setTimeout(() => {\n        const idx = this.waiters.findIndex(w => w.resolve === wrappedResolve);\n        if (idx >= 0) this.waiters.splice(idx, 1);\n        reject(new Error("Timeout aguardando resposta do FTP."));\n      }, this.timeoutMs);\n\n      const wrappedResolve = line => {\n        clearTimeout(timer);\n        resolve(line);\n      };\n      const wrappedReject = error => {\n        clearTimeout(timer);\n        reject(error);\n      };\n      this.waiters.push({ resolve: wrappedResolve, reject: wrappedReject });\n    });\n  }\n\n  async _readResponse() {\n    const first = await this._nextLine();\n    const match = first.match(/^(\\d{3})([ -])(.*)$/);\n    if (!match) throw new Error(`Resposta FTP invalida: ${first}`);\n\n    const code = Number(match[1]);\n    const lines = [first];\n\n    if (match[2] === "-") {\n      while (true) {\n        const line = await this._nextLine();\n        lines.push(line);\n        if (line.startsWith(`${code} `)) break;\n      }\n    }\n\n    return {\n      code,\n      message: lines.join("\\n")\n    };\n  }\n\n  async _send(command) {\n    if (!this.control || this.control.destroyed) {\n      throw new Error("FTP control socket nao esta conectado.");\n    }\n    this.control.write(command + "\\r\\n");\n    return await this._readResponse();\n  }\n\n  _assertOk(response, stage) {\n    if (response.code >= 200 && response.code < 400) return;\n    throw new Error(`${stage}: FTP ${response.code} ${response.message}`);\n  }\n\n  _localIpv4() {\n    let ip = this.control && this.control.localAddress;\n    if (ip && ip.startsWith("::ffff:")) ip = ip.slice(7);\n    if (!ip || !/^\\d+\\.\\d+\\.\\d+\\.\\d+$/.test(ip)) {\n      throw new Error(`Nao consegui determinar o IPv4 local para PORT: ${ip || "N/A"}`);\n    }\n    return ip;\n  }\n\n  async _prepareActiveData() {\n    const ip = this._localIpv4();\n    const server = net.createServer();\n\n    let resolveData;\n    let rejectData;\n    const dataPromise = new Promise((resolve, reject) => {\n      resolveData = resolve;\n      rejectData = reject;\n    });\n\n    server.once("connection", socket => {\n      socket.setTimeout(this.timeoutMs, () => {\n        socket.destroy(new Error("Timeout no canal de dados FTP ativo."));\n      });\n      resolveData(socket);\n      server.close();\n    });\n    server.once("error", rejectData);\n\n    await new Promise((resolve, reject) => {\n      server.once("error", reject);\n      server.listen({ host: ip, port: 0, exclusive: true }, resolve);\n    });\n\n    const address = server.address();\n    const port = Number(address.port);\n    const octets = ip.split(".").map(Number);\n    const p1 = Math.floor(port / 256);\n    const p2 = port % 256;\n\n    const response = await this._send(\n      `PORT ${octets[0]},${octets[1]},${octets[2]},${octets[3]},${p1},${p2}`\n    );\n\n    if (response.code < 200 || response.code >= 300) {\n      server.close();\n      throw new Error(`PORT recusado: FTP ${response.code} ${response.message}`);\n    }\n\n    return { server, dataPromise };\n  }\n\n  async _runDataCommand(command, consumeData) {\n    const active = await this._prepareActiveData();\n\n    try {\n      const preliminary = await this._send(command);\n      if (preliminary.code !== 125 && preliminary.code !== 150) {\n        throw new Error(`${command}: FTP ${preliminary.code} ${preliminary.message}`);\n      }\n\n      const dataSocket = await Promise.race([\n        active.dataPromise,\n        new Promise((_, reject) =>\n          setTimeout(() => reject(new Error(`Timeout aguardando conexao de dados para ${command}`)), this.timeoutMs)\n        )\n      ]);\n\n      const result = await consumeData(dataSocket);\n\n      const completed = await this._readResponse();\n      if (completed.code < 200 || completed.code >= 300) {\n        throw new Error(`${command}: FTP ${completed.code} ${completed.message}`);\n      }\n\n      return result;\n    } finally {\n      try { active.server.close(); } catch {}\n    }\n  }\n\n  _parseList(text) {\n    const out = [];\n\n    for (const raw of String(text).split(/\\r?\\n/)) {\n      const line = raw.trim();\n      if (!line) continue;\n\n      let m = line.match(/^([d-])\\S*\\s+\\S+\\s+\\S+\\s+\\S+\\s+(\\d+)\\s+\\S+\\s+\\S+\\s+\\S+\\s+(.+)$/);\n      if (m) {\n        const name = m[3];\n        if (name === "." || name === "..") continue;\n        out.push({\n          name,\n          isDirectory: m[1] === "d",\n          size: Number(m[2] || 0)\n        });\n        continue;\n      }\n\n      m = line.match(/^(\\d{2}-\\d{2}-\\d{2,4})\\s+(\\d{2}:\\d{2}(?:AM|PM)?)\\s+(<DIR>|\\d+)\\s+(.+)$/i);\n      if (m) {\n        const name = m[4];\n        if (name === "." || name === "..") continue;\n        out.push({\n          name,\n          isDirectory: String(m[3]).toUpperCase() === "<DIR>",\n          size: String(m[3]).toUpperCase() === "<DIR>" ? 0 : Number(m[3] || 0)\n        });\n        continue;\n      }\n\n      throw new Error(`Formato LIST do FTPdll nao reconhecido: ${line}`);\n    }\n\n    return out;\n  }\n\n  async list(remote = "/") {\n    const canonical = normalizeRemote(remote);\n    const target = ftpDllPath(canonical);\n\n    const text = await this._runDataCommand(`LIST ${target}`, async socket => {\n      socket.setEncoding("utf8");\n      let data = "";\n      await new Promise((resolve, reject) => {\n        socket.on("data", chunk => { data += chunk; });\n        socket.once("end", resolve);\n        socket.once("close", resolve);\n        socket.once("error", reject);\n      });\n      return data;\n    });\n\n    const items = this._parseList(text);\n    if (canonical === "/") {\n      for (const item of items) item.name = ftpDllRootDisplayName(item.name);\n    }\n    return items;\n  }\n\n  async cd(remote = "/") {\n    const response = await this._send(`CWD ${ftpDllPath(remote)}`);\n    if (response.code < 200 || response.code >= 300) {\n      throw new Error(`CWD falhou: FTP ${response.code} ${response.message}`);\n    }\n  }\n\n  async ensureDir(remoteDir) {\n    const target = ftpDllPath(remoteDir);\n    const parts = target.split("/").filter(Boolean);\n\n    await this.cd("/");\n\n    for (const part of parts) {\n      let response = await this._send(`CWD ${part}`);\n\n      if (response.code >= 400) {\n        const created = await this._send(`MKD ${part}`);\n        if (created.code < 200 || created.code >= 300) {\n          throw new Error(`MKD ${part}: FTP ${created.code} ${created.message}`);\n        }\n\n        response = await this._send(`CWD ${part}`);\n        if (response.code < 200 || response.code >= 300) {\n          throw new Error(`CWD ${part}: FTP ${response.code} ${response.message}`);\n        }\n      }\n    }\n  }\n\n  trackProgress(callback) {\n    this.progress = typeof callback === "function" ? callback : null;\n  }\n\n  async uploadFrom(localPath, remotePath) {\n    const target = ftpDllPath(remotePath);\n    let sent = 0;\n\n    await this._runDataCommand(`STOR ${target}`, async socket => {\n      const fs = require("fs");\n      const { pipeline } = require("stream/promises");\n      const input = fs.createReadStream(localPath);\n\n      input.on("data", chunk => {\n        sent += chunk.length;\n        if (this.progress) {\n          this.progress({\n            type: "upload",\n            bytes: sent,\n            name: path.basename(localPath)\n          });\n        }\n      });\n\n      await pipeline(input, socket);\n    });\n  }\n\n  close() {\n    try {\n      if (this.control && !this.control.destroyed) {\n        this.control.write("QUIT\\r\\n");\n        this.control.end();\n      }\n    } catch {}\n  }\n}\n'

if old not in text:
    raise SystemExit("ERRO: bloco connectFtp esperado nao foi encontrado; arquivo deixado intacto.")

backup = target.with_name(target.name + ".pre-active-ftp")
if not backup.exists():
    shutil.copy2(target, backup)
    print(f"Backup criado: {backup}")

patched = text.replace(old, active.rstrip() + "\n\n" + new, 1)
target.write_text(patched, encoding="utf-8")

try:
    subprocess.run(["node", "--check", str(target)], check=True)
except Exception:
    target.write_text(text, encoding="utf-8")
    raise SystemExit("ERRO: node --check falhou; server.js original foi restaurado.")

print("OK: FTPdll agora usa cliente FTP ativo (PORT); Aurora continua em basic-ftp/PASV.")
print("Mapeamento: Hdd1->fHdd, Usb0->fUsb0, Flash->fFlash.")
print("Reinicie o Companion antes de testar.")
